/* 环形缓冲区 ADT 接口定义 */
typedef struct {
    uint8_t *buf;          /* 指向分配好的内存 */
    volatile uint16_t head; /* ISR 更新：写入位置 */
    uint16_t tail;         /* 任务更新：读取位置 */
    uint16_t size;         /* 缓冲区大小（2的幂次方）*/
    uint16_t mask;         /* size - 1，用于位运算取模 */
    uint8_t overflow;      /* 溢出标志 */
} ringbuf_t;

void ringbuf_init(ringbuf_t *rb, uint8_t *mem, uint16_t sz);
uint16_t ringbuf_available(const ringbuf_t *rb);
int ringbuf_push(ringbuf_t *rb, uint8_t byte);
int ringbuf_pop(ringbuf_t *rb, uint8_t *byte);
uint8_t ringbuf_peek(const ringbuf_t *rb, uint16_t offset);

/* 环形缓冲区定义 —— 512 字节，2 的幂次方 */
#define RING_SIZE     512u
#define RING_MASK     (RING_SIZE - 1u)

static uint8_t rx_ring[RING_SIZE];
static volatile uint16_t rx_head = 0u;
static uint16_t rx_tail = 0u;

/* 初始化 DMA + 环形缓冲区 */
void uart_dma_init(void) {
    /* 清零缓冲区 */
    memset(rx_ring, 0, RING_SIZE);
    rx_head = 0u;
    rx_tail = 0u;
    /* 启动 DMA 循环接收，HAL 内部配置 DMA2_Stream2 */
    HAL_UART_Receive_DMA(&huart1,
                         rx_ring,
                         RING_SIZE);
}

/* DMA 传输完成回调 —— HT 和 TC 都走这里 */
void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart) {
    if (huart->Instance == USART1) {
        __DSB();  /* 确保 DMA 写入对所有核心可见 */
        rx_head = (rx_head + 1u) & RING_MASK;  /* 步进更新 */
        /* 重启 DMA 接收，Circular 模式下非必需但推荐 */
        HAL_UART_Receive_DMA(&huart1,
                             rx_ring,
                             RING_SIZE);
    }
}

/* 任务中读取可用数据 */
void task_process_uart(void) {
    uint16_t avail;
    uint8_t byte;
    /* 快照 head 和 tail，避免循环中被 ISR 修改 */
    do {
        avail = (rx_head >= rx_tail)
                ? (rx_head - rx_tail)
                : (RING_SIZE - rx_tail + rx_head);
    } while (avail != 0u &&
             (rx_head - rx_tail) != avail);
    /* 有数据则逐个读出 */
    while (avail-- > 0u) {
        if (HAL_UART_Receive(&huart1, &byte, 1u,
                             HAL_MAX_DELAY)
            == HAL_OK) {
            process_byte(byte);
        }
    }
}

/* 快照模式 —— 避免 ISR 在循环中修改 head 导致死锁 */
static inline uint16_t ringbuf_snapshot_available(
    const volatile uint16_t *head,
    const uint16_t *tail,
    uint16_t mask)
{
    uint16_t h = *head;  /* volatile read */
    uint16_t t = *tail;
    return (h >= t) ? (h - t) : (mask + 1u - t + h);
}

/* 安全读取循环 —— 使用快照值 */
void safe_read_loop(void) {
    uint16_t avail = ringbuf_snapshot_available(
                        &rx_head, &rx_tail,
                        RING_MASK);
    /* 限制单次最大处理量，防止饥饿 */
    if (avail > 256u) avail = 256u;
    while (avail-- > 0u) {
        uint8_t b = rx_ring[rx_tail];
        rx_tail = (rx_tail + 1u) & RING_MASK;
        process_byte(b);
    }
}

/* ===== 重构前：裸指针操作 ===== */
/* ❌ ISR 中直接操作 */
void DMA1_Channel4_IRQHandler(void) {
    static uint16_t h = 0;
    if (__HAL_DMA_GET_FLAG(&hdma, ...)) {
        __DSB();
        rx_buf[h++] = DMA_ReadData();  /* 裸写 */
        if (h >= 512) h = 0;            /* 硬编码绕回 */
    }
}

/* ❌ 主循环中也直接操作 */
void main_loop(void) {
    static uint16_t t = 0;
    while (t != h) {               /* 裸比较 */
        process(rx_buf[t++]);      /* 裸读取 */
        if (t >= 512) t = 0;       /* 硬编码绕回 */
    }
}

/* ===== 重构后：ADT 封装 ===== */
/* ✅ 统一的环形缓冲区接口 */
typedef struct {
    uint8_t *buf;
    volatile uint16_t head;
    uint16_t tail;
    uint16_t size;
    uint16_t mask;
    uint8_t overflow;
} ringbuf_t;

static inline void ringbuf_init(
    ringbuf_t *rb, uint8_t *mem,
    uint16_t sz) {
    rb->buf = mem;
    rb->head = 0;
    rb->tail = 0;
    rb->size = sz;
    rb->mask = sz - 1u;
    rb->overflow = 0;
}

static inline int ringbuf_push(
    ringbuf_t *rb, uint8_t byte) {
    uint16_t next = (rb->head + 1u)
                    & rb->mask;
    if (next == rb->tail) {        /* 满 */
        rb->overflow = 1;
        return -1;
    }
    rb->buf[rb->head] = byte;
    rb->head = next;
    return 0;
}

static inline int ringbuf_pop(
    ringbuf_t *rb, uint8_t *out) {
    if (rb->head == rb->tail)      /* 空 */
        return -1;
    *out = rb->buf[rb->tail];
    rb->tail = (rb->tail + 1u)
               & rb->mask;
    return 0;
}

/* ✅ ISR 中只用 push */
void DMA_Handler(void) {
    __DSB();
    ringbuf_push(&uart1_rb,
                 DMA_ReadData());
}

/* ✅ 主循环中只用 pop */
void main_loop(void) {
    uint8_t b;
    while (ringbuf_pop(&uart1_rb,
                       &b) == 0) {
        process_byte(b);
    }
}
